+      case T_INT:
+      case T_FLOAT:
+      case T_DOUBLE:
+        if (value_object_count == 0) {
+          SigEntry::add_entry(_sig, bt);
+        }
+        SigEntry::add_entry(_sig_cc, bt, nullptr, offset);
+        if (!skipping_inline_recv) {
