+  if (long_prev) {
+    // If previous bt was T_LONG and we reached the end of the signature, we know that it must be a T_OBJECT.
+    SigEntry::add_entry(_sig, T_OBJECT);
+    SigEntry::add_entry(_sig_cc, T_OBJECT);
